import React, { useEffect, useState } from 'react';
import { ArrowRight } from 'lucide-react';
import { hero } from '../data/content';

const TONE_STYLES = {
  primary: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 border-indigo-500/20',
  neutral: 'bg-zinc-500/10 text-zinc-600 dark:text-zinc-400 border-zinc-500/20',
  success: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20',
};

// Small one-shot typewriter for the terminal card. Runs once on mount.
function useTypewriter(lines, speed = 28, lineDelay = 350) {
  const [typed, setTyped] = useState(lines.map(() => ''));
  const [doneCount, setDoneCount] = useState(0);

  useEffect(() => {
    const timeouts = [];
    let cumulative = 0;

    lines.forEach((line, lineIdx) => {
      for (let i = 0; i <= line.length; i++) {
        timeouts.push(
          setTimeout(() => {
            setTyped((prev) => {
              const next = [...prev];
              next[lineIdx] = line.slice(0, i);
              return next;
            });
            if (i === line.length) setDoneCount((c) => c + 1);
          }, cumulative + i * speed)
        );
      }
      cumulative += line.length * speed + lineDelay;
    });

    return () => timeouts.forEach(clearTimeout);
  }, [lines, speed, lineDelay]);

  return { typed, doneCount };
}

export default function Hero() {
  const { typed, doneCount } = useTypewriter(hero.terminalLines);

  return (
    <section id="top" className="relative pt-28 sm:pt-36 pb-16 sm:pb-24 px-4 sm:px-6 bg-grid">
      <div className="max-w-6xl mx-auto grid lg:grid-cols-2 gap-12 items-center">
        <div>
          <p className="font-mono text-sm text-indigo-500 dark:text-indigo-400 mb-3">
            Hi, I'm {hero.eyebrow} 👋
          </p>
          <h1 className="font-display text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight text-zinc-900 dark:text-zinc-50">
            {hero.title}
          </h1>
          <p className="mt-6 text-base sm:text-lg text-zinc-600 dark:text-zinc-400 max-w-xl leading-relaxed">
            {hero.subtitle}
          </p>

          <div className="mt-6 flex flex-wrap gap-2">
            {hero.badges.map((badge) => (
              <span
                key={badge.label}
                className={`px-3 py-1 rounded-full text-xs font-mono border ${TONE_STYLES[badge.tone] || TONE_STYLES.neutral}`}
              >
                {badge.label}
              </span>
            ))}
          </div>

          <div className="mt-8 flex flex-wrap items-center gap-3">
            <a
              href={hero.primaryCta.href}
              className="group inline-flex items-center gap-2 px-5 py-2.5 rounded-full bg-indigo-500 text-white text-sm font-medium hover:bg-indigo-600 transition-colors"
            >
              {hero.primaryCta.label}
              <ArrowRight size={16} className="transition-transform group-hover:translate-x-0.5" />
            </a>
            <a
              href={hero.secondaryCta.href}
              className="inline-flex items-center gap-2 px-5 py-2.5 rounded-full border border-zinc-300 dark:border-zinc-700 text-zinc-700 dark:text-zinc-200 text-sm font-medium hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
            >
              {hero.secondaryCta.label}
            </a>
          </div>
        </div>

        {/* Terminal card */}
        <div className="hidden lg:block">
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl overflow-hidden">
            <div className="flex items-center gap-1.5 px-4 py-3 border-b border-zinc-200 dark:border-zinc-800">
              <span className="w-2.5 h-2.5 rounded-full bg-red-400" />
              <span className="w-2.5 h-2.5 rounded-full bg-amber-400" />
              <span className="w-2.5 h-2.5 rounded-full bg-emerald-400" />
              <span className="ml-3 font-mono text-xs text-zinc-400">chetanya@portfolio</span>
            </div>
            <div className="p-6 font-mono text-sm space-y-2 min-h-[140px]">
              {hero.terminalLines.map((line, idx) => (
                <div key={line} className="text-zinc-700 dark:text-zinc-300 whitespace-pre">
                  {idx === 0 && <span className="text-indigo-500 dark:text-indigo-400">$ </span>}
                  {typed[idx]}
                  {doneCount === idx && <span className="cursor-blink">▌</span>}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
